def stream_rows(resource, transform):
    """Lazily yield transform(row) for every row the resource provides.

    Each started iterator closes its resource exactly once, whether it
    reaches exhaustion, is closed explicitly, or its iteration or
    transformation raises.  A transform failure propagates and no
    further row is read.  Constructing or closing an unstarted
    generator performs no read and no close, because the body below
    only runs once iteration begins.

    If cleanup itself raises while an iteration or transform error is
    already active, the original error is preserved; otherwise the
    cleanup error propagates.
    """

    def gen():
        failed = False  # True while an iteration or transform error unwinds
        try:
            while True:
                try:
                    row = resource.read_next()
                except BaseException:
                    failed = True
                    raise
                if row is None:
                    break
                try:
                    result = transform(row)
                except BaseException:
                    failed = True
                    raise
                failed = False
                yield result
        finally:
            if failed:
                # An iteration or transform error is propagating: keep
                # the original error even if cleanup also raises.
                try:
                    resource.close()
                except BaseException:
                    pass
            else:
                resource.close()

    return gen()
